<?php
/** Browser A4 document, following the technical sheet's HTML/image print approach. */
final class SalesOrderConfirmationPrint
{
    public static function render(array $s): string
    {
        $company=$s['company'];$customer=$s['customer'];$order=$s['order'];
        $h=function($value){return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');};
        $date=function($value){$time=$value?strtotime($value):false;return $time?date('d/m/Y',$time):'—';};
        $number=function($value,$precision=2){return $value===null?'—':number_format((float)$value,$precision,',',' ');};
        $quantity=function($value)use($number){return rtrim(rtrim($number($value,4),'0'),',');};
        $logo=(string)($company['logo_data']??'');
        if($logo!==''&&!preg_match('#^(?:https?://|data:image/[^;]+;base64,)#i',$logo))$logo='';
        $total=0.0;$complete=true;foreach($s['lines'] as $line){if(($line['line_total']??null)===null)$complete=false;else $total+=(float)$line['line_total'];}
        ob_start();
        ?>
<!doctype html>
<html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($s['number'])?> · Confirmação de encomenda</title><style>
@page{size:A4 portrait;margin:10mm}*{box-sizing:border-box}body{margin:0;background:#e5e7eb;color:#17212b;font:9pt Arial,sans-serif;line-height:1.35}.actions{width:190mm;max-width:100%;margin:16px auto;display:flex;justify-content:flex-end;gap:8px}.actions button{padding:10px 16px;border:0;border-radius:6px;background:#28669b;color:#fff;font-weight:bold;cursor:pointer}.page{width:210mm;min-height:297mm;padding:10mm;margin:0 auto 24px;background:#fff;box-shadow:0 2px 12px #0003}.report-header{display:flex;justify-content:space-between;align-items:center;border-bottom:1.4px solid #333;padding-bottom:5mm;gap:6mm}.brand{width:55mm}.brand img{display:block;max-width:50mm;max-height:20mm;object-fit:contain}.company-name{font-size:20pt;font-weight:bold}.heading h1{font-size:15pt;margin:0}.heading span{font-size:10pt}.document-number{font-size:12pt;font-weight:bold;white-space:nowrap}.identity{display:grid;grid-template-columns:1fr 1fr;gap:12mm;margin:5mm 0 7mm}.identity p{margin:0 0 1mm}.customer-title{margin-top:5mm!important}.muted,.technical{color:#576573}.order-meta{border-top:1px solid #dbe1e7;padding:3mm 0;font-size:8pt}.order-meta p{margin:0 0 1mm}.lines{width:100%;border-collapse:collapse;table-layout:fixed;margin:3mm 0}.lines th{background:#eef1f5;text-align:left;font-size:8pt;padding:3mm 2mm}.lines td{border-bottom:1px solid #dbe1e7;padding:3mm 2mm;vertical-align:top;overflow-wrap:anywhere}.lines tr{break-inside:avoid;page-break-inside:avoid}.lines .qty{width:12%}.lines .description{width:58%}.lines .price{width:15%}.lines .value{width:15%}.lines .numeric{text-align:right;white-space:nowrap}.technical{font-size:7.5pt;margin-top:1mm}.unit{font-size:7pt;color:#576573}.total{display:flex;justify-content:flex-end;margin:5mm 0}.total div{background:#eef1f5;padding:3mm 4mm;display:flex;gap:12mm;font-weight:bold;font-size:11pt}.notes{margin:5mm 0;white-space:pre-wrap;overflow-wrap:anywhere}.footer{margin-top:12mm;font-size:7pt;break-inside:avoid;page-break-inside:avoid}.terms{white-space:pre-wrap;margin:3mm 0}.footer-meta{display:flex;justify-content:space-between;gap:5mm;border-top:1px solid #dbe1e7;padding-top:3mm;margin-top:8mm}thead{display:table-header-group}@media print{body{background:#fff}.actions{display:none}.page{width:auto;min-height:0;padding:0;margin:0;box-shadow:none}.report-header,.identity,.total{break-inside:avoid;page-break-inside:avoid}}@media screen and (max-width:820px){.page{margin:0;width:100%;min-height:0;padding:20px}.identity{gap:20px}.report-header{flex-wrap:wrap}.actions{padding:0 12px}}
</style></head><body>
<div class="actions"><button type="button" onclick="window.print()">Imprimir / Guardar PDF</button></div>
<main class="page"><header class="report-header"><div class="brand"><?php if($logo!==''):?><img src="<?=$h($logo)?>" alt="<?=$h($company['name'])?>"><?php else:?><span class="company-name"><?=$h($company['name'])?></span><?php endif;?></div><div class="heading"><h1>CONFIRMAÇÃO</h1><span>DE ENCOMENDA</span></div><div class="document-number"><?=$h($s['number'])?></div></header>
<section class="identity"><div><p><strong><?=$h($company['name'])?></strong></p><p><?=nl2br($h($company['address']??''))?></p><?php foreach(['phone'=>'Tel.','fax'=>'Fax','email'=>'Email','tax_number'=>'NIF'] as $key=>$label):if(trim((string)($company[$key]??''))==='')continue;?><p><?=$label?>: <?=$h($company[$key])?></p><?php endforeach;?></div><div><p>Data: <?=$date($s['issued_at'])?> · Moeda: <?=$h($s['currency'])?></p><p class="muted">Original</p><p class="customer-title"><strong>Cliente <?=$h($customer['code']??$order['customer_code']??'')?></strong></p><p><strong><?=$h($customer['name']??$order['customer_name']??'')?></strong></p><?php if(trim((string)($order['requisition_number']??''))!==''):?><p><strong>Nr. Requisição: <?=$h($order['requisition_number'])?></strong></p><?php endif;?><p class="customer-title"><strong>Morada</strong></p><p><?=$h(trim(($customer['address']??'').' '.($customer['address_2']??''))?:'Não registada')?></p><p><strong><?=$h(trim(($customer['postal_code']??'').' '.($customer['city']??'')))?></strong></p><p><?=$h($customer['country']??'')?></p><p>NIF: <?=$h(($customer['tax_number']??'')?:'—')?></p></div></section>
<section class="order-meta"><p>Encomenda <?=$h($order['order_number'])?> · Data da encomenda: <?=$date($order['order_date'])?> · Estado: <?=$h($order['status'])?></p><?php if(!empty($order['customer_reference'])):?><p>Referência do cliente: <?=$h($order['customer_reference'])?></p><?php endif;?><?php if(!empty($order['expected_date'])):?><p>Entrega prevista: <?=$date($order['expected_date'])?></p><?php endif;?></section>
<table class="lines"><thead><tr><th class="qty">Quant.</th><th class="description">Descrição</th><th class="price numeric">Preço U.</th><th class="value numeric">Valor</th></tr></thead><tbody><?php foreach($s['lines'] as $line):?><tr><td class="numeric"><?=$quantity($line['quantity'])?><div class="unit"><?=$h($line['unit_code']??'')?></div></td><td><strong><?=$h($line['description'])?></strong><?php if(!empty($line['technical_description'])):?><div class="technical"><?=$h($line['technical_description'])?></div><?php endif;?><?php if(!empty($line['expected_date'])):?><div class="technical">Entrega prevista: <?=$date($line['expected_date'])?></div><?php endif;?></td><td class="numeric"><?=$number($line['unit_price']??null,4)?><?php if((float)($line['discount_percent']??0)>0):?><div class="technical">Desc. <?=$quantity($line['discount_percent'])?>%</div><?php endif;?></td><td class="numeric"><?=$number($line['line_total']??null)?></td></tr><?php endforeach;?></tbody></table>
<section class="total"><div><span>Total (<?=$h($s['currency'])?>)</span><span><?=$complete?$number($total):'Não apurado'?></span></div></section><?php if(!$complete):?><p class="muted">Existem preços ou valores não registados.</p><?php endif;?><?php if(!empty($order['notes'])):?><section class="notes"><strong>Observações</strong><br><?=$h($order['notes'])?></section><?php endif;?>
<footer class="footer"><p>Valores sem IVA. Não constitui documento fiscal.</p><div class="footer-meta"><span>Modelo <?=$h($s['model'])?> · <?=$h($s['number'])?><?php if(trim((string)($company['terms']??''))!==''):?><br><span class="terms"><?=$h($company['terms'])?></span><?php endif;?></span><strong>GesTisser</strong></div></footer></main></body></html>
<?php
        return (string)ob_get_clean();
    }
}
